sys_variable_value.value:
#******* Format to access Input Parameters *******
# To use variable, prefix with '$'. eg. $message
# Read more https://docs.servicenow.com/?context=CSHelp:IntegrationHub-PowerShell-Step
#******* Reserved variables available when remoting type is Run on MID
# $computer   Host IP resolved from Connection alias
# $cred       Credential Object. Credential resolved via connection alias or credential alias. This can be used in conjunction with any cmd-let which support credential parameter eg. New-PSSession -credential $cred
# $log_info   mid property "mid.property.powershell.log_info" set on instance to enable debugging. So it's a flag available to act on and add any verbose logging if they want to in their script
Invoke-Command -ComputerName $computer -Credential $cred -Authentication Negotiate -ScriptBlock {
    param($csr, $ca_template_name, $ca_name)
    function cleanTempfiles() {
        param(
            [String[]] $files
        )
        Remove-Item -Path $files -Force -ErrorAction SilentlyContinue
    }
    try {
        #Step 1 --- Prepare and Clean any existing temporary files
        $req = [System.IO.Path]::GetTempFileName() 
        $cer = Join-Path -Path $env:TEMP -ChildPath "temp.cer"
        cleanTempFiles -files $cer
        #Step 2 --- Retrieve Microsoft CA name from domain configuration
        $clean_ca_name = ""
        #No CA Name was provided --- attempt to get the CA Name from LDAP automatically
        if(!$ca_name) {
            $rootDse = [System.DirectoryServices.DirectoryEntry]'LDAP://RootDSE'
            $sb = [System.DirectoryServices.DirectoryEntry]"LDAP://$($rootDse.configurationNamingContext)"
            $searcher = New-Object System.DirectoryServices.DirectorySearcher($sb, 'objectClass=pKIEnrollmentService')
            $cas = $searcher.FindAll()
            if($cas.Count -eq 1){
                $ca_name = "$($cas[0].Properties.dnshostname)\$($cas[0].Properties.cn)"
                $clean_ca_name = $ca_name
            } else {
                #No CA Name was provided --- Multiple CAs on Host can't resolve CA Name automatically
                throw "Multiple CAs on Host, Please provide CA Name in routing policy"
            }
        }
        if (!$ca_name -eq "") {
            $clean_ca_name = $ca_name
            $ca_name = " -config `"$ca_name`""
        }
        if(!$ca_template_name -eq "") {
            $ca_template_name = " -attrib `"CertificateTemplate:$ca_template_name`""
        }
        #Step 4 --- Execute request logic
        Set-Content -Path $req -Value $csr
        #Step 4.4 -- Submit request to CA
        $requestId = Invoke-Expression "certreq -f -q -submit $ca_template_name $ca_name `"$req`" `"$cer`" 2>&1"
        $requestId = ($requestId -split '\n')[0]
        $requestId = ($requestId -split ': ')[1]
        $requestId = [int]$requestId
        if (!($LastExitCode -eq 0)) {
            throw "certreq -f -q -submit command failed"
        }
        # Return the clean_ca_name and requestId for use by the Retrieve-Certificate script
        return @{
            CAName = $clean_ca_name
            RequestId = $requestId
            CertificatePath = $cer
        } | ConvertTo-Json
    } catch {
        Write-Error $_
    } finally {
        cleanTempfiles -files $req, $cer
    }
} -ArgumentList ($csr, $ca_template_name, $ca_name)

